function debounce(fn, ms) {
    let timeoutStarted;
    let timeoutAdded;
    let timeoutId; // thruthiness indicates whether active timeout
    function runWithTimeout(timeout) {
        timeoutStarted = Date.now();
        timeoutAdded = 0;
        timeoutId = setTimeout(() => {
            if (timeoutAdded) {
                runWithTimeout(timeoutAdded);
            }
            else {
                timeoutId = undefined;
                fn();
            }
        }, timeout);
    }
    function request() {
        if (timeoutId) {
            timeoutAdded = Date.now() - timeoutStarted;
        }
        else {
            runWithTimeout(ms);
        }
    }
    function cancel() {
        if (timeoutId) {
            clearTimeout(timeoutId);
            timeoutId = undefined;
        }
    }
    return [request, cancel];
}

class Store {
    constructor() {
        this.handlers = [];
    }
    set(value) {
        this.currentValue = value;
        for (let handler of this.handlers) {
            handler(value);
        }
    }
    subscribe(handler) {
        this.handlers.push(handler);
        if (this.currentValue !== undefined) {
            handler(this.currentValue);
        }
    }
}

/*
Subscribers will get a LIST of CustomRenderings
*/
class CustomRenderingStore extends Store {
    constructor() {
        super(...arguments);
        this.map = new Map();
    }
    // for consistent order
    handle(customRendering) {
        const { map } = this;
        let updated = false;
        if (customRendering.isActive) {
            map.set(customRendering.id, customRendering);
            updated = true;
        }
        else if (map.has(customRendering.id)) {
            map.delete(customRendering.id);
            updated = true;
        }
        if (updated) {
            this.set(map);
        }
    }
}

export { CustomRenderingStore, debounce };
